// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { createCollection, createItems, sortItems, getItems, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const collections = "sk_sort_atomic";
    const sort = "sort";

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collections, sort);

    expect(getValue(collectionsPostResponse, "data.collection"), 'collection').toBe(collections);
    expect(getValue(collectionsPostResponse, "data.meta.collection"), 'meta.collection').toBe(collections);
    expect(getValue(collectionsPostResponse, "data.meta.sort_field"), 'meta.sort_field').toBe(sort);
    expect(getValue(collectionsPostResponse, "data.meta.singleton"), 'meta.singleton').toBe(false);
    expect(getValue(collectionsPostResponse, "data.meta.hidden"), 'meta.hidden').toBe(false);

    const itemsPostResponse = await createItems(client, URL_localhost, headers, collections);

    expect(getValue(itemsPostResponse, "data.0.name"), 'seeded name 0').toBe("A");
    expect(getValue(itemsPostResponse, "data.0.sort"), 'seeded sort 0').toBe(1);
    expect(getValue(itemsPostResponse, "data.1.name"), 'seeded name 1').toBe("B");
    expect(getValue(itemsPostResponse, "data.1.sort"), 'seeded sort 1').toBe(2);
    expect(getValue(itemsPostResponse, "data.2.name"), 'seeded name 2').toBe("C");
    expect(getValue(itemsPostResponse, "data.2.sort"), 'seeded sort 2').toBe(3);
    expect(getValue(itemsPostResponse, "data.3.name"), 'seeded name 3').toBe("D");
    expect(getValue(itemsPostResponse, "data.3.sort"), 'seeded sort 3').toBe(4);
    expect(getValue(itemsPostResponse, "data.4"), 'seeded index 4 absent').toBeNull();
    expect(getValue(itemsPostResponse, "data.0.id"), 'seeded id 0').toBeGreaterThan(0);
    expect(getValue(itemsPostResponse, "data.1.id"), 'seeded id 1').toBeGreaterThan(0);
    expect(getValue(itemsPostResponse, "data.2.id"), 'seeded id 2').toBeGreaterThan(0);
    expect(getValue(itemsPostResponse, "data.3.id"), 'seeded id 3').toBeGreaterThan(0);

    const seededIdA = getValue(itemsPostResponse, "data.0.id");
    const seededIdB = getValue(itemsPostResponse, "data.1.id");
    const seededIdC = getValue(itemsPostResponse, "data.2.id");
    const seededIdD = getValue(itemsPostResponse, "data.3.id");

    const utils1PostResponse = await sortItems(client, URL_localhost, headers, sort, collections);

    expect(getValue(utils1PostResponse, "errors.0.message"), 'errors.0.message').toBe("Cannot read properties of undefined (reading 'sort')");
    expect(getValue(utils1PostResponse, "errors.0.extensions.code"), 'errors.0.extensions.code').toBe("INTERNAL_SERVER_ERROR");
    expect(getValue(utils1PostResponse, "errors.1"), 'errors.1 absent').toBeNull();

    const itemsGetResponse = await getItems(client, URL_localhost, headers, collections, sort);

    expect(getValue(itemsGetResponse, "data.0.id"), 'position 0 id unchanged').toBe(seededIdA);
    expect(getValue(itemsGetResponse, "data.0.name"), 'position 0 name unchanged').toBe("A");
    expect(getValue(itemsGetResponse, "data.0.sort"), 'position 0 sort unchanged').toBe(1);
    expect(getValue(itemsGetResponse, "data.1.id"), 'position 1 id unchanged').toBe(seededIdB);
    expect(getValue(itemsGetResponse, "data.1.name"), 'position 1 name unchanged').toBe("B");
    expect(getValue(itemsGetResponse, "data.1.sort"), 'position 1 sort unchanged').toBe(2);
    expect(getValue(itemsGetResponse, "data.2.id"), 'position 2 id unchanged').toBe(seededIdC);
    expect(getValue(itemsGetResponse, "data.2.name"), 'position 2 name unchanged').toBe("C");
    expect(getValue(itemsGetResponse, "data.2.sort"), 'position 2 sort unchanged').toBe(3);
    expect(getValue(itemsGetResponse, "data.3.id"), 'position 3 id unchanged').toBe(seededIdD);
    expect(getValue(itemsGetResponse, "data.3.name"), 'position 3 name unchanged').toBe("D");
    expect(getValue(itemsGetResponse, "data.3.sort"), 'position 3 sort unchanged').toBe(4);
    expect(getValue(itemsGetResponse, "data.4"), 'index 4 absent').toBeNull();
    expect(getValue(itemsGetResponse, "data.0.sort"), 'ordering direction ascending').toBeLessThan(getValue(itemsGetResponse, "data.1.sort"));
    expect(getValue(itemsGetResponse, "errors.0.message"), 'no errors on read-back').toBeNull();

    await deleteCollection(client, URL_localhost, headers, collections);
});
